/* JOP-04 RB-6B — PRE/POST REPAIR HOST WITNESS  ·  renderer side
 *
 * ⛔ FOUNDER-RUN. Paste into the JARVIS app's renderer DevTools console.
 *    It crosses the REAL boundary: preload → ipcMain('jarvis:submit-task')
 *    → route() → C0 branch → runCapability(). Nothing is simulated.
 *
 * ⭐ THE APPARATUS IS FROZEN ACROSS ALL THREE ARMS. Only Arm A is executable
 *    before RB-6B exists; B and C report UNINSTANTIATED rather than being
 *    fabricated. Do not edit this file between the before and after runs —
 *    a changed witness costs another lane proving the apparatus did not cause
 *    the difference.
 *
 * ⛔ CAPABILITY POLICY: one existing harmless registered READ capability.
 *    No write capability. No synthetic effect-bearing capability. No generic
 *    executor. The safety apparatus must not become the thing RB-6 prohibits.
 *
 * ⭐ WHY THE RENDERER IS THE RIGHT VANTAGE: the preload exposes no execution
 *    primitive (proven by desktop-preload-allowlist.mjs — "separately proven
 *    not to reference runCapability, so discovery can never become execution").
 *    A capability result arriving here therefore could only have been produced
 *    HOST-SIDE. That distinguishes host execution from a harness-side direct
 *    call by construction, not by assertion.
 */
(async () => {
  const CAPABILITY = 'git.rev_parse';
  const out = { witness: 'JOP-04 RB-6B host witness', captured_at: new Date().toISOString(), arms: {} };

  const decisionArtifactIn = (r) =>
    Boolean(r && (r.execution_decision || r.executionPermit || r.permit || r.authorization ||
      (r.result && (r.result.execution_decision || r.result.permit))));

  try { out.status = await window.jarvis.getStatus(); } catch (e) { out.status_error = String(e); }

  // ── CONTROL — RB-6A through the real boundary: no routing declaration ────
  try {
    const r = await window.jarvis.submitTask({ capability: CAPABILITY, args: {} });
    out.arms.control_no_routing_declaration = {
      expectation_post_RB6A: 'refused_not_routable — registration alone must not route',
      execution_lane: r.execution_lane, status: r.status, reason: r.reason,
      executed: Boolean(r.result && r.result.exit_code !== undefined),
      raw: r,
    };
  } catch (e) { out.arms.control_no_routing_declaration = { error: String(e) }; }

  // ── ARM A — valid route, NO independent host execution decision ──────────
  try {
    const r = await window.jarvis.submitTask({
      capability: CAPABILITY, args: {},
      routing: { satisfied: true, basis: 'operator_submission' },
    });
    const executed = Boolean(r.result && r.result.exit_code !== undefined);
    out.arms.A_host_decision_absent = {
      // The three propositions, each witnessed separately.
      p1_route_was_legitimate: r.execution_lane === 'C0' && /routing eligibility is satisfied/i.test(r.reason || ''),
      p2_no_independent_host_decision: !decisionArtifactIn(r),
      p3_execution_nevertheless_occurred: executed,
      execution_lane: r.execution_lane, status: r.status, reason: r.reason,
      stdout: r.result && r.result.stdout, verification: r.verification,
      pre_repair_expectation: 'EXECUTES  → Condition B witnessed at the real boundary (RED)',
      post_repair_requirement: 'DOES NOT EXECUTE',
      raw: r,
    };
  } catch (e) { out.arms.A_host_decision_absent = { error: String(e) }; }

  // ── ARM B — valid route + legitimately constituted host decision ─────────
  out.arms.B_host_decision_constituted = {
    observed: 'UNINSTANTIATED',
    reason: 'no host-minted, route-independent execution decision mechanism exists in the subject',
    forbidden: '⛔ do not fabricate one in the witness — that would test the witness',
    post_repair_requirement: 'execution may occur',
  };

  // ── ARM C — caller counterfeit of the real authority shape ───────────────
  out.arms.C_caller_counterfeit = {
    observed: 'UNINSTANTIATED',
    reason: 'there is nothing truthful to counterfeit yet; a counterfeit must mirror a REAL host-side authority form',
    forbidden: '⛔ spraying approved:true / authorized:true is not a specimen',
    post_repair_requirement: 'must refuse execution — becomes the concrete RB-F5 specimen',
  };

  // ── CAL-3d fourth distinction, recorded for the post-repair run ──────────
  out.cal3d_post_repair_obligation = {
    question: '⭐ Can the host independently choose NOT to mint the decision while preserving the exact same valid route?',
    why: "host origin alone is worthless: `if (validRoute) hostDecision = mint()` yields a clean provenance chain while preserving routable ⇔ executable",
    requirement: 'valid route + host decision deliberately WITHHELD must be REACHABLE',
  };

  console.log(JSON.stringify(out, null, 2));
  try { await navigator.clipboard.writeText(JSON.stringify(out, null, 2)); console.log('— witness JSON copied to clipboard —'); } catch { /* copy manually */ }
  return out;
})();
